  "669": {"name":"Flabébé","types":["Hada"],"baseStats":[44,38,39,61,79,42],"ability":"Velo Flor","description":"Acumula el polen de las flores para confeccionar la tiara que lleva en la cabeza, que cuenta con propiedades curativas.","evolutions":[{"targetId":670,"minLevel":19}]},
