  "672": {"name":"Skiddo","types":["Planta"],"baseStats":[66,65,48,62,57,52],"ability":"Herbívoro","description":"Puede generar energía con las hojas que tiene en la espalda disponiendo tan solo de agua y luz solar. Gracias a ello puede sobrevivir sin comer.","evolutions":[{"targetId":673,"minLevel":32}]},
