  "740": {"name":"Crabominable","types":["Lucha","Hielo"],"baseStats":[97,132,77,62,67,43],"ability":"Corte Fuerte","description":"No se lo piensa dos veces a la hora de zurrar. Se tiene constancia de que sus puñetazos frenéticos han llegado a detener aludes.","evolutions":[]},
