  "826": {"name":"Orbeetle","types":["Bicho","Psíquico"],"baseStats":[60,45,110,80,120,90],"ability":"Enjambre","description":"Se sirve de sus poderes psíquicos, con los que es capaz de percibir lo que ocurre en un radio de 10 km, para examinar sus alrededores.","evolutions":[]},
