  "833": {"name":"Chewtle","types":["Agua"],"baseStats":[50,64,50,38,38,44],"ability":"Mandíbula Fuerte","description":"El cuerno que tiene en la cabeza es duro como una roca. Lo usa para atacar al rival y, cuando este baja la guardia, lo muerde y no lo suelta.","evolutions":[{"targetId":834,"minLevel":22}]},
  "834": {"name":"Drednaw","types":["Agua","Roca"],"baseStats":[90,115,90,48,68,74],"ability":"Mandíbula Fuerte","description":"Su cuello extensible le permite alcanzar a los rivales a distancia. Hundiendo sus afilados dientes, les da el golpe de gracia.","evolutions":[]},
  "835": {"name":"Yamper","types":["Eléctrico"],"baseStats":[59,45,50,40,50,26],"ability":"Recogebolas","description":"Son muy glotones, por lo que ayudan a la gente a cambio de comida. Echan chispas al correr.","evolutions":[{"targetId":836,"minLevel":25}]},
