  "837": {"name":"Rolycoly","types":["Roca"],"baseStats":[30,40,50,40,50,30],"ability":"Combustible","description":"Recorre incluso los caminos más impracticables y pedregosos como si de un monociclo se tratase. La combustión de carbón es su fuente vital.","evolutions":[{"targetId":838,"minLevel":18}]},
  "838": {"name":"Carkol","types":["Roca","Fuego"],"baseStats":[80,60,90,60,70,50],"ability":"Combustible","description":"Gira las patas a gran velocidad para correr a unos 30 km/h. Emite llamas a una temperatura de 1000 °C.","evolutions":[{"targetId":839,"minLevel":34}]},
  "839": {"name":"Coalossal","types":["Roca","Fuego"],"baseStats":[110,80,120,80,90,30],"ability":"Combustible","description":"Cuando se enzarza en un combate, la montaña de carbón arde al rojo vivo y esparce chispas que calcinan todo lo que le rodea.","evolutions":[]},
  "840": {"name":"Applin","types":["Planta","Dragón"],"baseStats":[40,40,80,40,40,20],"ability":"Maduración","description":"Nada más nacer se refugia en una manzana, cuyo interior va devorando a medida que crece. El sabor de la fruta determina la evolución.","evolutions":[{"targetId":841,"minLevel":1,"requiredItem":"Manzana Ácida"},{"targetId":842,"minLevel":1,"requiredItem":"Manzana Dulce"},{"targetId":1011,"minLevel":1,"requiredItem":"Manzana Melosa"}]},
