  "842": {"name":"Appletun","types":["Planta","Dragón"],"baseStats":[110,85,80,100,80,30],"ability":"Maduración","description":"Su cuerpo está recubierto de néctar. La piel de la espalda es tan dulce que los niños de antaño solían tomarla como merienda.","evolutions":[]},
  "843": {"name":"Silicobra","types":["Tierra"],"baseStats":[52,57,75,35,50,46],"ability":"Expulsarena","description":"Expulsa arena por los orificios nasales. Una vez que aturde al enemigo, aprovecha la ocasión para ocultarse bajo tierra.","evolutions":[{"targetId":844,"minLevel":36}]},
