  "845": {"name":"Cramorant","types":["Volador","Agua"],"baseStats":[70,85,55,85,95,85],"ability":"Tragamisil","description":"Traga Arrokuda enteros debido a su glotonería, tan notable que en ocasiones ingiere hasta otros Pokémon sin querer.","evolutions":[]},
