  "852": {"name":"Clobbopus","types":["Lucha"],"baseStats":[50,68,60,50,50,32],"ability":"Flexibilidad","description":"Su inteligencia es similar a la de un niño de tres años. Sus tentáculos se desprenden a menudo, pero ni se inmuta, ya que se regeneran solos.","evolutions":[{"targetId":853,"minLevel":30}]},
